{
  "identity": {
    "name": "Ardent Industries Inc.",
    "location": "1020 N. Franklin Blvd Suite 101, Nampa, ID 83687",
    "claims": [
      {
        "statement": "The business operates from a facility in Nampa, Idaho.",
        "label": "fact",
        "sourceUrl": "https://ardentindustries.net/",
        "quote": "1020 N. Franklin Blvd Suite 101 Nampa, ID 83687"
      },
      {
        "statement": "The formal corporate name of the business is Ardent Industries Inc.",
        "label": "fact",
        "sourceUrl": "https://ardentindustries.net/",
        "quote": "© 2026 Ardent Industries Inc. All rights reserved."
      }
    ]
  },
  "industry": {
    "industry": "Precision Metal Fabrication & CNC Machining",
    "activities": [
      "Precision sheet metal fabrication",
      "CNC milling and turning",
      "Powder coating",
      "MIG and TIG welding",
      "Manufactured accessory e-commerce sales"
    ],
    "claims": [
      {
        "statement": "Ardent Industries specializes in sheet metal fabrication, CNC machining, powder coating, and welding services.",
        "label": "fact",
        "sourceUrl": "https://ardentindustries.net/",
        "quote": "We specialize in precision sheet metal fabrication, CNC machining, powder coating, and welding services in Nampa, Idaho, and the surrounding Treasure Valley."
      },
      {
        "statement": "The company serves diverse industrial clients across semiconductor, robotics, chemical processing, and automotive aftermarket sectors.",
        "label": "fact",
        "sourceUrl": "https://ardentindustries.net/",
        "quote": "Ardent Industries provides top-notch metal fabrication solutions for a wide range of industries, including but not limited to semiconductor, robotics, chemical processing, home furnishings, electronic components,"
      },
      {
        "statement": "The business is a contract manufacturing machine shop rather than a residential HVAC, plumbing, or electrical trade contractor.",
        "label": "inference",
        "sourceUrl": "https://ardentindustries.net/",
        "quote": null
      }
    ]
  },
  "publicInformation": {
    "officialWebsite": "https://ardentindustries.net/",
    "claims": [
      {
        "statement": "Ardent Industries was founded in California in 2014 and relocated to Idaho in 2017.",
        "label": "fact",
        "sourceUrl": "https://ardentindustries.net/about-us/",
        "quote": "Ardent Industries was established in California in 2014, relocating to Idaho in 2017."
      },
      {
        "statement": "The shop utilizes specialized machining equipment including a Haas VF2-SS Vertical Machining Center and a Bridgeport Vertical Mill.",
        "label": "fact",
        "sourceUrl": "https://ardentindustries.net/machining/",
        "quote": "Haas VF2-SS Vertical Machining Center Travels - (X) 30\" x (Y) 16\" x (Z) 20\" Bridgeport Vertical Mill 2 Axis with Prototrak CNC MX3 Control"
      }
    ]
  },
  "licensing": {
    "claims": [
      {
        "statement": "Ardent Industries asserts corporate registration status through its formal copyright notice.",
        "label": "fact",
        "sourceUrl": "https://ardentindustries.net/",
        "quote": "© 2026 Ardent Industries Inc. All rights reserved."
      },
      {
        "statement": "The company is registered as an active domestic or foreign business entity with the Idaho Secretary of State.",
        "label": "hypothesis",
        "sourceUrl": null,
        "quote": null
      }
    ],
    "limitations": "The company's website does not list specific state contractor license numbers, Idaho corporate filing IDs, or trade specialty certifications."
  },
  "existingSoftware": [
    {
      "product": "WooCommerce",
      "purpose": "E-commerce product catalog and online checkout processing",
      "evidence": {
        "statement": "The website operates an online store with product listings and direct cart additions.",
        "label": "fact",
        "sourceUrl": "https://ardentindustries.net/products/",
        "quote": "Milwaukee Packout Wall Mount – Large $ 59.99"
      }
    },
    {
      "product": "CAD/CAM Software",
      "purpose": "Computer-aided design and machine toolpath programming for precision parts",
      "evidence": {
        "statement": "Shop technicians design parts and specifications using advanced CAD/CAM software.",
        "label": "fact",
        "sourceUrl": "https://ardentindustries.net/machining/",
        "quote": "Our skilled technicians use advanced CAD/CAM software to design parts that meet your exact requirements,"
      }
    },
    {
      "product": "Elementor Pro / WordPress",
      "purpose": "Content management and visual page layout infrastructure",
      "evidence": {
        "statement": "The public website frontend is built and delivered on WordPress with Elementor layout components.",
        "label": "inference",
        "sourceUrl": "https://ardentindustries.net/",
        "quote": null
      }
    }
  ],
  "opportunityEvidence": [
    {
      "statement": "Customer inquiries and RFQs are directed to a generic email inbox and a standard contact web form.",
      "label": "fact",
      "sourceUrl": "https://ardentindustries.net/contact-us/",
      "quote": "Feel free to contact Ardent Industries with any questions regarding your manufacturing needs. We look forward to hearing from you."
    },
    {
      "statement": "The website hosts a digital store with only two active retail product offerings.",
      "label": "fact",
      "sourceUrl": "https://ardentindustries.net/products/",
      "quote": "Showing all 2 results Default sorting Sort by popularity Sort by average rating Sort by latest Sort by price: low to high Sort by price: high to low"
    },
    {
      "statement": "Because Ardent Industries is a manufacturing job shop rather than a residential field-service business, ForgeX's home-service lead-to-job workflows do not apply.",
      "label": "inference",
      "sourceUrl": "https://ardentindustries.net/",
      "quote": null
    }
  ],
  "problems": [
    {
      "problem": "Target segment misalignment: Ardent Industries operates in industrial contract manufacturing and CNC machining rather than residential HVAC, plumbing, or electrical contracting.",
      "label": "fact",
      "basis": "The company's service offerings are explicitly precision sheet metal fabrication, machining, powder coating, and welding for industrial clients (https://ardentindustries.net/)."
    },
    {
      "problem": "Operational intake relies on engineering print evaluation and custom RFQ scoping rather than residential consumer lead dispatching.",
      "label": "hypothesis",
      "basis": "Custom manufacturing job shops require technical CAD/CAM reviews, material cost calculations, and machine tolerance feasibility rather than instant appointment bookings."
    },
    {
      "problem": "Staffing and operational scale may not fit ForgeX's 10 to 75 field-service technician profile.",
      "label": "hypothesis",
      "basis": "Machine shops operate around capital equipment and machining centers rather than mobile field-service fleets paying for consumer lead volume."
    }
  ],
  "existingSolutions": [
    {
      "solution": "Manufacturing Job Shop ERP (e.g., JobBOSS, ProShop, or E2 Shop System)",
      "addresses": "B2B quoting, bill of materials management, CNC machine scheduling, and production job routing.",
      "alreadyOwned": false
    },
    {
      "solution": "WooCommerce WordPress Platform",
      "addresses": "Direct customer orders and payments for standardized off-the-shelf fabricated products.",
      "alreadyOwned": true
    }
  ],
  "forgexSolutions": [],
  "feasibility": {
    "rating": "not applicable",
    "explanation": "ForgeX provides fixed-price automation solutions specifically tailored to owner-led home-service contractors. Because Ardent Industries is a precision manufacturing and machine shop, ForgeX's productized workflows are not applicable."
  },
  "aiDelivery": {
    "rating": "not applicable",
    "explanation": "No ForgeX solution is recommended or viable for this contract manufacturing business."
  },
  "humanReview": [
    "Technical print and tolerance review by experienced machinists and fabricators for all incoming RFQs.",
    "Engineering validation of material specifications, machine capabilities, and run times.",
    "Order confirmation and shipping verification for direct e-commerce and commercial shipments."
  ],
  "risks": [
    {
      "type": "operational",
      "description": "Applying consumer home-service lead automation to custom industrial RFQs risks alienating engineering clients who require custom technical quoting."
    },
    {
      "type": "compliance",
      "description": "Manufacturing parts for aerospace, defense, or semiconductor sectors often involves proprietary engineering drawings and strict compliance obligations (e.g., ITAR, NDA) requiring secure, restricted document workflows."
    },
    {
      "type": "security",
      "description": "Public web forms and e-commerce checkout mechanisms require regular maintenance to prevent form abuse, spam, and payment transaction vulnerabilities."
    }
  ],
  "commercial": {
    "supportable": false,
    "value": null,
    "implementationCost": null,
    "assumptions": []
  },
  "contacts": {
    "decisionMakerRoles": [
      "President",
      "Owner",
      "General Manager",
      "Operations Manager"
    ],
    "people": [],
    "channels": [
      {
        "kind": "phone",
        "value": "[redacted]",
        "sourceUrl": "https://ardentindustries.net/"
      },
      {
        "kind": "email",
        "value": "[redacted]",
        "sourceUrl": "https://ardentindustries.net/"
      },
      {
        "kind": "web form",
        "value": "https://ardentindustries.net/contact-us/",
        "sourceUrl": "https://ardentindustries.net/contact-us/"
      }
    ]
  },
  "discovery": {
    "questions": [
      "What system is currently used to manage custom RFQs, engineering prints, and machine scheduling?",
      "How are technical inquiries received through the website routed to estimating and CAD/CAM programmers?",
      "Does Ardent Industries intend to expand standardized e-commerce product lines alongside custom job shop manufacturing?"
    ],
    "outreachSubject": "",
    "outreachBody": ""
  },
  "evidence": {
    "sourcesUsed": [
      {
        "url": "https://ardentindustries.net/",
        "usedFor": "Identity, verified address, phone, email, and principal metalworking/machining activities"
      },
      {
        "url": "https://ardentindustries.net/about-us/",
        "usedFor": "Company history, founding date (2014 in CA, 2017 move to ID), and service area"
      },
      {
        "url": "https://ardentindustries.net/contact-us/",
        "usedFor": "Contact form details, general inquiry messaging, and embed map location"
      },
      {
        "url": "https://ardentindustries.net/products/",
        "usedFor": "E-commerce product pricing, WooCommerce store presence, and catalog inventory"
      },
      {
        "url": "https://ardentindustries.net/machining/",
        "usedFor": "CNC machinery inventory (Haas, Bridgeport) and CAD/CAM software usage"
      },
      {
        "url": "https://ardentindustries.net/media/",
        "usedFor": "Operational equipment mentions (Mitsubishi laser) and job shop activities"
      }
    ],
    "limitations": [
      "No individual owners, founders, or operational managers are named on the public pages read.",
      "The total internal employee headcount is not stated on the website.",
      "Specific internal ERP, accounting, or estimating software products used in the shop cannot be verified from public pages."
    ]
  },
  "qualification": {
    "category": "not a fit",
    "rationale": "Ardent Industries Inc. is a precision sheet metal fabrication, CNC machining, welding, and powder coating contract manufacturer. It serves B2B industrial clients across sectors such as semiconductor, robotics, and automotive. It is not an owner-led residential home-service contractor (HVAC, plumbing, or electrical) and does not acquire retail service leads. Consequently, the company falls outside ForgeX's target segment and none of ForgeX's service catalog offerings are applicable."
  }
}
